  `login_as_disabled` tinyint(1) DEFAULT '0',
  `plain_password` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `public_id` (`public_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10000017 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
